// Package cgofile tests that the files of a cgo package are analyzed (#186).
// The driver gives the analyzer cmd/cgo's output, which starts with
// "// Code generated by cmd/cgo; DO NOT EDIT." for every file.
package cgofile

// #include <stdlib.h>
// static int twice(int x) { return 2 * x; }
import "C"

import (
	"unsafe"

	"gorm.io/gorm"
)

func reuse(db *gorm.DB) {
	db = db.Session(&gorm.Session{})
	q := db.Where("x")
	q.Find(nil)
	q.Count(nil) // want `\*gorm\.DB reused: second branch from mutable root`
}

// reuseAroundC calls C, so cgo rewrites the body and adds //line directives
// inside it. The ignore directive still applies to the line below it.
func reuseAroundC(db *gorm.DB) {
	p := C.malloc(C.size_t(C.twice(8)))
	defer C.free(unsafe.Pointer(p))
	q := db.Where("x")
	q.Find(nil)
	//gormreuse:ignore
	q.Count(nil)
	q.Count(nil) // want `\*gorm\.DB reused: second branch from mutable root`
	_ = C.twice(C.int(1))
}

//gormreuse:ignore
func ignored(db *gorm.DB) {
	q := db.Where("x")
	q.Find(nil)
	q.Count(nil)
}

func helper(q *gorm.DB) { //gormreuse:pure
	_ = C.twice(1)
	_ = q
}

func usesPure(db *gorm.DB) {
	q := db.Where("base")
	helper(q)
	q.Find(nil)
}
